Definition is_leaf (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : Prop :=
  exists tags, nth_error G.CPS i = Some c /\ nth_error G.TAGS i = Some tags /\ nth_error (CC.cp_PSS c) k = Some ps /\ nth_error tags k = Some t.
Lemma wl_at : forall i c k ps t, is_leaf i c k ps t -> wl_chk i c k ps t = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$i;R+0$c;R+aJ$k;R+0$ps;R+aK$t;R+aL$IL;R!5'aM#5#4#3#2#1!:'aN'aO'aP'aQ'aR#6#5#4#3#2#1").
Qed.
Lemma retw_at : forall i c k ps t, is_leaf i c k ps t -> retw_chk i c k ps t = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$i;R+0$c;R+aJ$k;R+0$ps;R+aK$t;R+aL$IL;R!5'aM#5#4#3#2#1!:'aN'aO'aP'aS'aT#6#5#4#3#2#1").
Qed.
