Lemma vlt_some : forall n o e, vlt n o = true -> o = Some e -> APC.expr_vars_lt n e = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S20!1+C+bK!2,G+bK#3$n;R+0$o;R0$e;R+bK$H;R!3+4+^H!2'cK#3#2,^I$H0;R!3+40#3!2,G+bK#2!7'@01$o;R0%H;R!3+4+^H!2'cK#6#1,^I!3+4+^H!2'cL#7#5,^I$H;R!3+4+^H!2'cK#51,^I#1#4#1#2").
