Lemma cut_at : forall i, (i < 79)%nat ->
  let n := CC.cp_nx (cutn i) in
  (forall e, CPX i = Some e -> APC.expr_vars_lt n e = true) /\ (forall e, CP2X i = Some e -> APC.expr_vars_lt n e = true) /\
  (forall e, SIZX i = Some e -> APC.expr_vars_lt n e = true) /\ (forall e, PTRX i = Some e -> APC.expr_vars_lt n e = true) /\
  (forall e, TAGX i = Some e -> APC.expr_vars_lt n e = true) /\
  (KD i <> KEntry -> (62 <= n)%nat) /\ (forall sst, KD i = KAtc sst -> (80 <= n)%nat /\ APC.expr_vars_lt n (A0X i) = true /\ APC.expr_vars_lt n (ECVX i) = true) /\
