Definition stepping (i : nat) (sst cc : Z) : Prop := KD i = KStep sst cc \/ (KD i = KText /\ sst = 0 /\ cc = 0).
Lemma rb_setec : forall i c k ps, is_leaf i c k ps (CC.TOther SETEC) ->
  exists code j sst cc, PSA.reg_of ps 11 = ELit code /\ code <> 0 /\ CH2.ret_of G.RETS i k = Some j /\ KD j = KSetEc code /\
