Definition retcells (i j : nat) (cells : list kentry) (c : CC.cutpoint) (esz : expr) (g : nat) : Prop :=
  CPX j = cellv cells 148 4 /\ CP2X j = cellv cells 152 4 /\ TAGX j = cellv cells 220 1 /\ cellv cells 232 8 = Some (size_of (CC.cp_know c)) /\ SIZX j = Some esz /\ PTRX j = Some (EVar g).
Lemma size_of_SIZX : forall i x, SIZX i = Some x -> size_of (CC.cp_know (cutn i)) = x.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S20!1+C+bK!1'e3!1'aW#3$i;R+0$x;R+bK$H;R!3+40!1'bU#2!2,G+bK#1vd!6'@0!2,G+bK#2$o;R0!3+4+bK-CRN$x;R!1+C+bK+bK#12$e;R+bK#1!1,c6,3#3!2,A+bK#2!3'cI1!1,=|768;}8#1!3+4+bK!1'e21#2").
Qed.
Lemma size_of_eq : forall cells x, cellv cells 232 8 = Some x -> size_of cells = x.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S30!1+C+bK!1,=|768;}8$cells;R!1+5+b@$x;R+bK$H;R!3+40!3'cI#212!2,G+bK#1vd!6'@0!2,G+bK#2$o;R0!3+4+bK-CRN$x;R!1+C+bK+bK#12$e;R+bK#1!1,c6,3#3!2,A+bK#2!3'cI#312#1!3+4+bK!1'e2#3#2").
