Lemma rb_push : forall i c k ps, is_leaf i c k ps (CC.TOther PUSHB) ->
  exists cc o j, KD i = KStep SS_ESC cc /\ hasb (SR.ps_cells ps) cc = true /\ tagcP i (SR.ps_cells ps) /\ PSA.reg_of ps 11 = ELit o /\
    allb (admlist (SR.ps_cells ps) BV) (fun b => match sdesc SS_ESC b with SGo s' UKeep UKeep [o'] => (s' =? SS_TEXT) && (o' =? o) | _ => false end)%bool = true /\
