Lemma rb_conv : forall i c k ps, is_leaf i c k ps (CC.TOther CONVERT) ->
  exists u8 j, KD i = KConv u8 /\ tagcP i (SR.ps_cells ps) /\ CH2.ret_of G.RETS i k = Some j /\ KD j = (if u8 then KStep SS_TEXT 1 else KRet4) /\
    PSA.reg_of ps 10 = (if u8 then ADD (V 55) (ELit 112) else ADD (V 10) (ELit 148)) /\
    (if u8 then cellb (SR.ps_cells ps) 55 112 4 = Some PAIRX /\ CPX i = Some (V 57) else cellv (SR.ps_cells ps) 148 4 = Some (V 57) /\ CPX i = Some (V 57)) /\
