Lemma rb_app : forall i c k ps, is_leaf i c k ps (CC.TOther APPEND) ->
  let cells := SR.ps_cells ps in let adm := admlist cells BV in
  exists j, CH2.ret_of G.RETS i k = Some j /\ tagcP i cells /\ retcells i j cells c (APC.eadd (size_of cells) (PSA.reg_of ps 12)) (PSA.gof ps i c (cutn j) 4368 2) /\
  ((KD i = KText /\ PSA.reg_of ps 11 = RUNS /\ hasb cells 0 = true /\
     ((PSA.reg_of ps 12 = RUNL /\ allb adm (fun b => b =? 92) = true /\ KD j = KStep SS_ESC 1) \/
      (PSA.reg_of ps 12 = RUNL /\ allb adm (fun b => b =? 34) = true /\ KD j = KStep SS_TEXT 0) \/
