(* [comment removed for export] *)
Lemma rb_goto_step : forall i c k ps j s sst cc (istext : bool),
  is_leaf i c k ps (CC.TGoto j s) -> (KD i = KStep sst cc /\ istext = false) \/ (KD i = KText /\ sst = 0 /\ cc = 0 /\ istext = true) ->
  let cells := SR.ps_cells ps in let adm := admlist cells BV in
  (KD j = KRetx /\ istext = false /\ exh_fact cells cc = true /\ cellv cells 209 1 = Some (ELit sst) /\ sub s 78 = curform cc /\
     keep_ok (CPX i) 57 (sub s 88) sst = true /\ keep_ok (CP2X i) 58 (sub s 89) sst = true /\ tagcP i cells /\
     (needs 57 sst = true -> cellv cells 148 4 = CPX i) /\ (needs 58 sst = true -> cellv cells 152 4 = CP2X i))
  \/ (exists dj cj sstj, (KD j = KStep sstj cj \/ (KD j = KText /\ sstj = 0 /\ cj = 0)) /\
        ((sub s 51 = JM1 /\ dj = 1) \/ (sub s 51 = V 51 /\ dj = 0)) /\
        tag_ok i (sub s 59) = true /\ buf_ok i (sub s 53) (sub s 54) = true /\
        (KD j = KText -> (istext = true /\ sub s 61 = V 61) \/ (istext = false /\ sub s 61 = sboform cc)) /\
        ( (cj + dj - cc = 0 /\ sstj = sst /\ keep_ok (CPX i) 57 (sub s 57) sstj = true /\ keep_ok (CP2X i) 58 (sub s 58) sstj = true /\ istext = false)
        \/ (cj + dj - cc = 1 /\ istext = match KD j with KText => true | _ => false end /\ someb adm = true /\ hasb cells cc = true /\
              allb adm (fun b => match sdesc sst b with
                                | SGo s' u1 u2 out => (s' =? sstj) && Nat.eqb (length out) (if istext then 1%nat else 0%nat) &&
