Lemma rb_goto_atc : forall i c k ps j s sst,
  is_leaf i c k ps (CC.TGoto j s) -> KD i = KAtc sst ->
  let cells := SR.ps_cells ps in let adm := admlist cells BV in let a0 := A0X i in
  (KD j = KRetx /\ hasr cells (ECVX i) 1 31 = true /\ cellv cells 209 1 = Some (ELit sst) /\ sub s 78 = curform 0 /\ hasb cells 0 = true)
  \/ (tag_ok i (sub s 59) = true /\ buf_ok i (sub s 53) (sub s 54) = true /\ hasr cells (ECVX i) 0 0 = true /\ hasb cells 0 = true /\
      ( (exists sstj, KD j = KStep sstj 0 /\ sub s 51 = JM1 /\
           allb adm (fun b => match hexval b with None => true | Some _ =>
                           match sdesc sst b with
                           | SGo s' u1 u2 [] =>
                               (s' =? sstj) &&
                               match u1 with UKeep => keep_ok (CPX i) 57 (sub s 57) sstj | _ => expr_eqb (sub s 57) a0 end &&
                               match u2 with UKeep => keep_ok (CP2X i) 58 (sub s 58) sstj | _ => expr_eqb (sub s 58) a0 end
                           | SU4 _ => (sstj =? SS_SP1) && match lit cells (fe_hs a0) with Some true => true | _ => false end && expr_eqb (sub s 57) a0 && keep_ok (CP2X i) 58 (sub s 58) sstj
                           | _ => false end end)%bool = true)
        \/ (KD j = KConv false /\ sst = SS_U4 /\ sub s 51 = V 51 /\ lit cells (fe_hs a0) = Some false /\ sub s 57 = a0 /\ CPX j = Some (V 57))
