(* [comment removed for export] *)
Lemma rb_goto_other : forall i c k ps j s,
  is_leaf i c k ps (CC.TGoto j s) -> match KD i with KStep _ _ | KText | KAtc _ => False | _ => True end ->
  let cells := SR.ps_cells ps in
  (KD i = KEntry /\ ((exists sstj, KD j = KStep sstj 0 /\ hasr cells (V 41) sstj sstj = true /\ sub s 51 = V 32 /\ sub s 57 = V 44 /\ sub s 58 = V 45 /\ sub s 59 = V 48 /\
                                   sub s 53 = V 35 /\ sub s 54 = V 36 /\ (1 <= j <= 23)%nat)
                     \/ (KD j = KRetx /\ hasr cells (V 41) 1 1 = true /\ cellv cells 209 1 = Some (ELit 1) /\ hasr cells (SLTUE (V 11) ENDE) 0 0 = true /\ sub s 78 = V 11 /\
                           cellv cells 220 1 = Some (V 48))))
  \/ (KD i = KRet4 /\ KD j = KRetx /\ sub s 78 = curform 1 /\ cellv cells 209 1 = Some (ELit 0) /\ tagcP i cells)
