(* [comment removed for export] *)
Lemma sdesc_hex : forall sst b d, hexst sst = true -> hexval b = Some d ->
  (sst = 2 /\ sdesc sst b = SGo 3 (USet d) UKeep []) \/ (3 <= sst <= 4 /\ sdesc sst b = SGo (sst + 1) (UHex d) UKeep []) \/ (sst = 5 /\ sdesc sst b = SU4 d) \/
  (sst = 8 /\ sdesc sst b = SGo 9 UKeep (USet d) []) \/ (9 <= sst <= 10 /\ sdesc sst b = SGo (sst + 1) UKeep (UHex d) []) \/ (sst = 11 /\ sdesc sst b = SU8 d).
